from pathlib import Path
import re,base64
R=Path('output/presentation-update');src=Path('C:/Users/AKENA/Downloads/neoguard_3d_presentation_v2.html').read_text(encoding='utf-8');sections=re.findall(r'<section.*?</section>',src,re.S)
def txt(i,body):
 sections[i]=re.sub(r'<div class="txt">.*?(?=<div class="art">)', '<div class="txt">'+body+'</div>',sections[i],count=1,flags=re.S)
def art(i,body):
 pos=sections[i].index('<div class="art">');sections[i]=sections[i][:pos]+'<div class="art">'+body+'</div></section>'
def source(s):return '<p class="source">'+s+'</p>'
txt(1,'''<div class="kicker">Main objective &amp; specific objectives</div><h2>Monitor locally.<br>Support earlier warning.</h2><p>Design, develop, test and evaluate a low-cost, offline-capable neonatal monitor for local hypothermia and hypoxia warnings, with AI risk scoring and trend analysis when connected.</p><ol class="objectives"><li><b>Design:</b> integrate sensors, display, alerts and timekeeping.</li><li><b>Develop:</b> connect firmware, API, database, AI and dashboard.</li><li><b>Test:</b> verify components and integrated dataflow.</li><li><b>Evaluate:</b> measure performance against a threshold-only baseline.</li></ol>'''+source('Proposal §1.3 · Report §§1.3–1.4, 7.3–7.6'))
txt(2,'''<div class="kicker">01 · Problem statement</div><h2>The gap between observation rounds.</h2><p>The proposal identifies a need in rural Ugandan clinics for affordable, continuous monitoring of temperature, oxygen saturation and heart rate despite unreliable connectivity and power.</p><p>Intermittent checks can leave deterioration unnoticed. A useful system must warn at the bedside and preserve readings when connectivity fails.</p><span class="chip">Multiple vital signs</span><span class="chip">Offline local alerts</span><span class="chip">Traceable history</span>'''+source('Project problem framing: Proposal §1.2 · Battery endurance remains unqualified.'))
txt(5,'''<div class="kicker">02 · Objective 1 — Design hardware</div><h2>One integrated sensing path.</h2><ul class="list"><li><b>Sense:</b> MAX30102 + MLX90614 on I²C.</li><li><b>Record:</b> ESP32-S3, DS1302 and microSD.</li><li><b>Respond:</b> ST7789 display, RGB LED and buzzer.</li></ul><p class="verdict">Achieved at prototype integration level.</p><p>Recorded SPI-carrier checks: <b>0 ERC, 0 DRC, 0 unrouted and 0 schematic-parity violations.</b></p><p class="small">Design revision: proposed LCD + DS3231 → implemented ST7789 + DS1302. Measurement accuracy and physical fit still require qualification.</p>'''+source('Report §§7.3.2, 7.3.6 · NeoGuard SPI-D carrier'))
def img(path):return 'data:image/png;base64,'+base64.b64encode(Path(path).read_bytes()).decode()
figs=[]
for path,title in [('pcb/schematic-1.png','Schematic · controller & sensors'),('pcb/PCB-SPI.png','PCB · routed SPI carrier'),('pcb/schematic-2.png','Schematic · display interface'),('pcb/schematic-3.png','Schematic · power interface')]:
 figs.append(f'<button class="figure" onclick="openFigure(this)" aria-label="Enlarge {title}"><img src="{img(path)}" alt="{title}"><span>{title} ↗</span></button>')
art(5,'<div class="figures">'+''.join(figs)+'</div><p class="small">Actual NeoGuard design files · select a figure to enlarge</p>')
txt(6,'''<div class="kicker">03 · Objective 2 — Develop firmware</div><h2>Local alerts remain independent.</h2><p>The ESP32 samples, validates and timestamps readings, applies local thresholds, then stores and synchronises data.</p><ul class="list"><li><b>Abnormal reading:</b> display, LED and buzzer respond locally.</li><li><b>No connection:</b> buffer readings on microSD.</li><li><b>Connection restored:</b> upload queued records.</li></ul><p class="small"><b>Recorded runs:</b> 588 / 230 saved rows; 0 sampler resets and 0 temperature-packet errors in both. Runtime, heartbeat and sync returned HTTP 200.</p>'''+source('Report §7.4.3 · Two diagnostic runs, not endurance trials'))
txt(7,'''<div class="kicker">04 · Objective 2 — Develop the platform</div><h2>From readings to a shared view.</h2><p><b>Flask + PostgreSQL</b> store patients, devices, sessions, readings, alerts and risk scores.</p><p><b>React</b> presents current values, histories, alert timelines and risk explanations. Access controls scope the records to authorised users.</p><p class="verdict">Achieved as a working prototype.</p><p class="small"><b>Recorded checkpoint:</b> 21 backend tests passed; 4 database migrations applied with no reported schema differences. Dashboard delay was not quantified.</p>'''+source('Report §§7.4–7.5 · Results reported at the recorded checkpoint'))
txt(9,'''<div class="kicker">06 · Objectives 3 &amp; 4 — Test and evaluate</div><h2>Evidence, with clear limits.</h2><p><b>Testing — partly achieved.</b> Firmware build/upload, SD diagnostics and API checks passed; 21 backend tests passed. Reference accuracy, timing and controlled offline trials remain incomplete.</p><p><b>Evaluation — partly achieved.</b> AI assessed on <b>480 synthetic sessions</b>: 288 train / 96 validation / 96 test; <b>19,272 held-out rows</b>.</p><p class="small">AI row-level precision <b>0.9377</b> · recall <b>0.8177</b> · ROC-AUC <b>0.9748</b>. These are simulation results, not clinical accuracy.</p>'''+source('Report §§7.5–7.6 · Threshold selected on validation data'))
art(9,'''<div class="evidence"><h3>Synthetic event comparison</h3><table><thead><tr><th>Metric</th><th>AI</th><th>Threshold only</th></tr></thead><tbody><tr><td>Events detected at onset</td><td>44 / 49</td><td>25 / 49</td></tr><tr><td>Event sensitivity</td><td>89.8%</td><td>51.0%</td></tr><tr><td>Median lead time</td><td>107.5 s</td><td>0 s</td></tr><tr><td>False-warning episodes/hour</td><td>1.4197</td><td>0.7472</td></tr></tbody></table><p class="small">Earlier detection came with more false-warning episodes. Event sensitivity and row-level recall measure different things.</p></div>''')
# Clinical scope: demonstration readings and non-contact skin temperature are not validated core temperature.
sections[0]=sections[0].replace('An offline-first neonatal vital-sign monitor','An offline-first neonatal monitoring research prototype')
sections[3]=sections[3].replace('Red light · Infrared light','Illustrative readings · not clinical measurements')
sections[4]=sections[4].replace('Infrared energy from the skin is measured from a distance, so the baby is not disturbed.','The sensor estimates surface temperature from infrared energy. Clinical interpretation requires controlled distance, calibration and comparison with a reference thermometer.')
# Preserve all original slide positions, animated backgrounds and base styling.
it=iter(sections);out=re.sub(r'<section.*?</section>',lambda m:next(it),src,flags=re.S)
css='''<style id="presentation-additions">
.slide{padding:4vw;gap:3vw}.slide h2{font-size:clamp(1.8rem,3.1vw,3.5rem);line-height:1.08;margin:.45em 0}.slide p{font-size:clamp(.95rem,1.38vw,1.35rem);line-height:1.45;margin:.65em 0}.slide .small{font-size:clamp(.8rem,1.08vw,1rem);line-height:1.4}.slide .source{font-size:clamp(.65rem,.85vw,.85rem);color:#c3d4e3;margin-top:1em}.objectives{padding-left:1.25em;font-size:clamp(.85rem,1.2vw,1.15rem);line-height:1.5}.objectives li{margin:.35em 0}.slide .list{font-size:clamp(.95rem,1.3vw,1.2rem)}.verdict{color:#55e6a5;font-weight:750}.figures{display:grid;grid-template-columns:1fr 1fr;gap:12px}.figure{cursor:zoom-in;border:1px solid #4de3ff88;background:#071a2de6;border-radius:12px;overflow:hidden;padding:8px;color:#eef7ff;text-align:left;font:inherit}.figure img{width:100%;height:17vh;object-fit:contain;background:#fff;border-radius:5px}.figure span{display:block;font-size:clamp(.65rem,.9vw,.9rem);padding-top:7px}.evidence{background:#06111ce8;border:1px solid #4de3ff77;padding:24px;border-radius:18px}.evidence h3{font-size:1.3rem;margin:0 0 16px}.evidence table{border-collapse:collapse;width:100%;font-size:clamp(.85rem,1.15vw,1.15rem)}.evidence td,.evidence th{padding:14px 7px;text-align:left;border-bottom:1px solid #ffffff33}.evidence th{color:#f6d060}.evidence td:nth-child(2){color:#55e6a5;font-weight:bold}#figure-view{width:96vw;height:94vh;max-width:none;max-height:none;background:#06111c;color:white;border:1px solid #4de3ff;border-radius:16px;padding:18px}#figure-view::backdrop{background:#000d}#figure-view img{width:100%;height:calc(100% - 60px);object-fit:contain;background:white}#figure-view button{float:right;padding:10px 20px;cursor:pointer}#figure-view h3{margin:0 0 16px}@media(max-height:700px){.slide{padding:3vw}.slide p{font-size:1rem}.slide .small{font-size:.85rem}.list li{padding:.3em 0}.evidence td,.evidence th{padding:9px 5px}.objectives{font-size:.95rem}}@media(max-width:760px){.slide{overflow-y:auto;grid-template-columns:1fr;padding:26px;gap:12px}.slide h2{font-size:2rem}.art .b3d{width:55vw}.figure img{height:16vh}.evidence{padding:14px}.slide .source{font-size:.7rem}}
</style>'''
out=out.replace('</head>',css+'</head>')
modal='''<dialog id="figure-view"><button onclick="document.getElementById('figure-view').close()">Close ×</button><h3></h3><img alt=""></dialog><script>function openFigure(button){const d=document.getElementById('figure-view'),im=button.querySelector('img');d.querySelector('img').src=im.src;d.querySelector('img').alt=im.alt;d.querySelector('h3').textContent=im.alt;d.showModal()}document.getElementById('figure-view').addEventListener('keydown',e=>e.stopPropagation());</script>'''
out=out.replace('</body>',modal+'</body>')
R.joinpath('NeoGuard_public_presentation.html').write_text(out,encoding='utf-8')
# Verify original animations, embedded background assets and background nodes are unmodified.
assert re.findall(r'<div class="bg">.*?</div></div>',src,re.S)==re.findall(r'<div class="bg">.*?</div></div>',out,re.S)
assert re.findall(r'<script>\(function.*?</script>',src,re.S)==re.findall(r'<script>\(function.*?</script>',out,re.S)
assert len(sections)==12
print('Updated 12 slides; original background nodes and navigation script preserved.')
